// Even more installations for every country (the US already has its own detailed list): every
// named military area in OpenStreetMap (landuse=military) that the other files don't already
// cover, classified by name in many languages (missile bases, air bases, naval bases, garrisons,
// headquarters, training areas, academies, depots, radar sites). Police, border guards, interior
// ministry troops, historic sites, foreign-run bases and occupied ground are left out. Each country
// is filled up to a density set by its active troops (0.6 bases per thousand, 40 to 700), and the
// new rows' share of its weights is capped so the researched distribution stays in charge.
// Map data © OpenStreetMap contributors (ODbL). Same row format as js/deployments.js.
